rules.css:
/* Angular hosts. A custom element is an inline box unless a rule says otherwise; these rules have
   zero specificity. Layout primitives carry their class on the host, which sets display where the
   class does. Page header, alert and the cards keep an inner element and need a box around it. */
:where(hw-container, hw-section, hw-aspect-ratio, hw-page-header, hw-alert) { display: block; }
:where(hw-card, hw-service-card) { display: grid; }

/* CopyButton. The button is an ordinary Hawiyah button. The status element is announced politely
   and is visible only after a failure, beside the control the reader used. No new tokens. */
.hw-copy { position: relative; display: inline-flex; flex-wrap: wrap; align-items: center; gap: var(--hw-space-2); min-inline-size: 0; max-inline-size: 100%; vertical-align: middle; }
.hw-copy-message { margin: 0; color: var(--hw-color-danger); font-family: var(--hw-font-sans); font-size: var(--hw-text-sm); line-height: var(--hw-leading-normal); overflow-wrap: anywhere; }
.hw-copy:not([data-state='failed']) > .hw-copy-message { position: absolute; inline-size: 1px; block-size: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (forced-colors: active) { .hw-copy-message { color: CanvasText; } }

/* SideNavigation: the same list outside a drawer. The row, group, current-marker, focus, disabled
   and forced-colours rules above apply unchanged. The application may set --hw-side-navigation-top
   and --hw-side-navigation-bottom-reserve as placement. */
.hw-side-navigation { display: block; box-sizing: border-box; inline-size: 100%; min-inline-size: 0; padding-block-start: 0; color: var(--hw-color-text); font-family: var(--hw-font-sans); }
@media (min-width: 64rem) {
  .hw-side-navigation[data-sticky='true'] {
    position: sticky; align-self: start; inset-block-start: var(--hw-side-navigation-top, var(--hw-space-4));
    max-block-size: calc(100dvh - var(--hw-side-navigation-top, var(--hw-space-4)) - var(--hw-side-navigation-bottom-reserve, var(--hw-space-4)));
    overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin;
  }
}
